def _myers_edit_distance(a: list[str], b: list[str]) -> int:
    n = len(a)
    m = len(b)

    if n == 0:
        return m
    if m == 0:
        return n

    max_d = n + m
    offset = max_d + 1
    v = [0] * (2 * max_d + 3)
    v[offset + 1] = 0

    for d in range(max_d + 1):
        for k in range(-d, d + 1, 2):
            idx = k + offset

            if k == -d or (k != d and v[idx - 1] < v[idx + 1]):
                x = v[idx + 1]
            else:
                x = v[idx - 1] + 1

            if x > n:
                x = n

            y = x - k

            while x < n and y < m and a[x] == b[y]:
                x += 1
                y += 1

            if x < n:
                v[idx] = x
            else:
                v[idx] = n

            if x == n and y == m:
                return d

    return max_d


def shortest_edit_script(a: list[str], b: list[str]) -> list[tuple]:
    n = len(a)
    m = len(b)

    d = _myers_edit_distance(a, b)

    if d == 0:
        return [("=", i, i) for i in range(n)]

    inf = d + 1
    off = n - m

    lo_arr = [0] * (n + 1)
    hi_arr = [0] * (n + 1)
    dist_rows = [[] for _ in range(n + 1)]

    for i in range(n, -1, -1):
        lo = i - off - d
        if lo < 0:
            lo = 0
        hi = i - off + d
        if hi > m:
            hi = m

        lo_arr[i] = lo
        hi_arr[i] = hi

        length = hi - lo + 1
        if length <= 0:
            dist_rows[i] = []
            continue

        vals = [inf] * length

        if i == n:
            for idx in range(length):
                vals[idx] = m - (lo + idx)
            dist_rows[i] = vals
            continue

        next_lo = lo_arr[i + 1]
        next_hi = hi_arr[i + 1]
        next_vals = dist_rows[i + 1]
        next_len = next_hi - next_lo + 1

        ai = a[i]

        for idx in range(length - 1, -1, -1):
            j = lo + idx

            if j == m:
                vals[idx] = n - i
                continue

            if ai == b[j]:
                k = j + 1 - next_lo
                if 0 <= k < next_len:
                    vals[idx] = next_vals[k]
                continue

            best = inf

            k = j - next_lo
            if 0 <= k < next_len:
                best = next_vals[k]

            if idx + 1 < length:
                cand = vals[idx + 1]
                if cand < best:
                    best = cand

            if best < inf:
                dist = best + 1
                if dist > inf:
                    dist = inf
                vals[idx] = dist

        dist_rows[i] = vals

    def get_dist(i: int, j: int) -> int:
        if i < 0 or i > n or j < 0 or j > m:
            return inf
        lo = lo_arr[i]
        hi = hi_arr[i]
        if lo <= j <= hi:
            return dist_rows[i][j - lo]
        return inf

    script: list[tuple] = []
    i = 0
    j = 0
    used = 0
    budget = d

    while i < n or j < m:
        if i < n and j < m and a[i] == b[j]:
            if get_dist(i + 1, j + 1) == budget:
                script.append(("=", i, j))
                i += 1
                j += 1
                continue

        if i < n and budget > 0:
            if get_dist(i + 1, j) == budget - 1:
                script.append(("-", i))
                i += 1
                used += 1
                budget -= 1
                continue

        if j < m and budget > 0:
            if get_dist(i, j + 1) == budget - 1:
                script.append(("+", j))
                j += 1
                used += 1
                budget -= 1
                continue

        if i < n:
            script.append(("-", i))
            i += 1
        elif j < m:
            script.append(("+", j))
            j += 1

    return script
